        // Display initial game ready message
        renderingEngine.message(StringResources.GAME_READY_MESSAGE);

        // Initial render of the game state
        renderingEngine.render(state);

        // Main game loop
        while (!shouldStop()) {
            // Fetch action from input
            Action action = inputEngine.fetchAction();

            // Check if action is null (exit command)
            if (action == null) {
                renderingEngine.message(StringResources.GAME_EXIT_MESSAGE);
                break;
            }

            // Process the action
            ActionResult result = processAction(action);

            // Handle action result
            if (result instanceof ActionResult.Failed) {
                ActionResult.Failed failed = (ActionResult.Failed) result;
                renderingEngine.message(failed.getReason());
            }

            // Render the updated game state
            renderingEngine.render(state);

            // Check win condition
            if (state.isWin()) {
                renderingEngine.message(StringResources.WIN_MESSAGE);
                break;
            }
        }
    }
}
